/** The generated widget cell, provided by the plugin in `vite.ts`. */
declare module "virtual:moku-neo4j-widget" {
  /** Python source of the cell that defines `CypherGraph`. */
  export const source: string;
  /** A content hash identifying this generation of the cell. */
  export const version: string;
  /** The text starting the cell's first line, followed by its version. */
  export const marker: string;
}
